/* CSS PART 1 OF 2 */

/* =========================================================
   JOSH BROOKS CONSTRUCTION — DESIGN SYSTEM
   ========================================================= */

:root {
  color-scheme: light;
  --ink: #202a2d;
  --ink-soft: #394649;
  --muted: #687477;
  --paper: #f7f6f2;
  --white: #ffffff;
  --surface: #eeede7;
  --line: #deded6;
  --forest: #263f3b;
  --forest-deep: #192f2c;
  --copper: #b66d45;
  --copper-dark: #955435;
  --gold: #d4ad78;

  --font-heading: "Georgia", "Times New Roman", serif;
  --font-body: "Arial", "Helvetica Neue", sans-serif;

  --container: 1180px;
  --gutter: clamp(22px, 5vw, 76px);
  --section-space: clamp(76px, 9vw, 124px);

  --radius-sm: 4px;
  --radius-md: 9px;
  --shadow: 0 16px 45px rgba(25, 47, 44, 0.10);
  --transition: 180ms ease;
}

/* RESET */

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  scroll-padding-top: 100px;
}

body {
  margin: 0;
  background: var(--paper);
  color: var(--ink);
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.7;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

img {
  display: block;
  max-width: 100%;
  height: auto;
}

a {
  color: inherit;
  text-decoration: none;
}

button,
input,
textarea,
select {
  font: inherit;
}

button,
a {
  -webkit-tap-highlight-color: transparent;
}

button {
  cursor: pointer;
}

::selection {
  background: var(--forest);
  color: var(--white);
}

:focus-visible {
  outline: 3px solid var(--copper);
  outline-offset: 4px;
}

/* TYPOGRAPHY */

h1,
h2,
h3,
h4 {
  margin: 0;
  color: var(--ink);
  font-family: var(--font-heading);
  font-weight: 400;
  line-height: 1.12;
  letter-spacing: -0.035em;
}

h1 {
  font-size: clamp(46px, 6.2vw, 78px);
}

h2 {
  font-size: clamp(36px, 4.4vw, 54px);
}

h3 {
  font-size: clamp(23px, 2.5vw, 30px);
}

p {
  margin: 0 0 20px;
}

.lead {
  max-width: 650px;
  color: var(--muted);
  font-size: clamp(17px, 1.5vw, 19px);
  line-height: 1.8;
}

.eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 22px;
  color: var(--copper-dark);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.17em;
  line-height: 1.4;
  text-transform: uppercase;
}

.eyebrow::before {
  width: 30px;
  height: 1px;
  background: var(--copper);
  content: "";
}

.section-heading {
  max-width: 720px;
  margin-bottom: 24px;
}

.section-intro {
  max-width: 640px;
  color: var(--muted);
  font-size: 17px;
  line-height: 1.8;
}

.text-copper {
  color: var(--copper-dark);
}

/* SHARED LAYOUT */

.container {
  width: min(var(--container), calc(100% - var(--gutter) * 2));
  margin-inline: auto;
}

.section {
  padding-block: var(--section-space);
}

.section--light {
  background: var(--paper);
}

.section--white {
  background: var(--white);
}

.section--dark {
  background: var(--forest);
  color: rgba(255, 255, 255, 0.82);
}

.section--dark h2,
.section--dark h3 {
  color: var(--white);
}

.section--dark .section-intro {
  color: rgba(255, 255, 255, 0.72);
}

.section-rule {
  width: 54px;
  height: 3px;
  margin: 28px 0;
  background: var(--copper);
}

/* HEADER AND NAVIGATION */

.site-header {
  position: relative;
  z-index: 20;
  background: var(--white);
  border-bottom: 1px solid rgba(32, 42, 45, 0.09);
}

.header-inner {
  display: flex;
  min-height: 94px;
  align-items: center;
  justify-content: space-between;
  gap: 32px;
}

.brand {
  display: inline-flex;
  flex: 0 0 auto;
  align-items: center;
  gap: 14px;
}

.brand img {
  width: 74px;
  height: 66px;
  object-fit: contain;
}

.brand-copy {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.brand-name {
  color: var(--forest-deep);
  font-family: var(--font-heading);
  font-size: 19px;
  font-weight: 700;
  letter-spacing: -0.025em;
  line-height: 1.2;
}

.brand-description {
  color: var(--muted);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.main-nav {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: clamp(18px, 2.6vw, 36px);
}

.main-nav a:not(.button) {
  position: relative;
  padding-block: 10px;
  color: var(--ink-soft);
  font-size: 12px;
  font-weight: 700;
  transition: color var(--transition);
}

.main-nav a:not(.button)::after {
  position: absolute;
  right: 0;
  bottom: 3px;
  left: 0;
  height: 1px;
  background: var(--copper);
  content: "";
  transform: scaleX(0);
  transform-origin: left;
  transition: transform var(--transition);
}

.main-nav a:not(.button):hover {
  color: var(--copper-dark);
}

.main-nav a:not(.button):hover::after {
  transform: scaleX(1);
}

.header-phone {
  color: var(--forest);
  font-size: 13px;
  font-weight: 700;
  white-space: nowrap;
}

/* BUTTONS */

.button {
  display: inline-flex;
  min-height: 52px;
  align-items: center;
  justify-content: center;
  gap: 12px;
  padding: 14px 24px;
  border: 1px solid transparent;
  border-radius: var(--radius-sm);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.045em;
  line-height: 1.3;
  text-align: center;
  transition:
    background var(--transition),
    color var(--transition),
    border-color var(--transition),
    transform var(--transition);
}

.button:hover {
  transform: translateY(-2px);
}

.button--primary {
  background: var(--copper);
  color: var(--white);
}

.button--primary:hover {
  background: var(--copper-dark);
}

.button--dark {
  background: var(--forest);
  color: var(--white);
}

.button--dark:hover {
  background: var(--forest-deep);
}

.button--outline {
  border-color: rgba(255, 255, 255, 0.65);
  background: transparent;
  color: var(--white);
}

.button--outline:hover {
  border-color: var(--white);
  background: var(--white);
  color: var(--forest);
}

.button--outline-dark {
  border-color: var(--forest);
  background: transparent;
  color: var(--forest);
}

.button--outline-dark:hover {
  background: var(--forest);
  color: var(--white);
}

.button-arrow {
  font-size: 17px;
  line-height: 1;
}

/* HERO */

.hero {
  position: relative;
  display: flex;
  min-height: 650px;
  align-items: center;
  overflow: hidden;
  background: var(--forest-deep);
  color: var(--white);
}

.hero::before {
  position: absolute;
  inset: 0;
  background:
    linear-gradient(
      90deg,
      rgba(20, 39, 36, 0.97) 0%,
      rgba(20, 39, 36, 0.88) 42%,
      rgba(20, 39, 36, 0.24) 100%
    ),
    url("https://joshbrooksconstructionllc.com/wp-content/uploads/2026/09/finished-roof-ridge-thornton-co-768x1024.jpg")
      center 43% / cover no-repeat;
  content: "";
}

.hero::after {
  position: absolute;
  right: 0;
  bottom: 0;
  left: 0;
  height: 5px;
  background: var(--copper);
  content: "";
}

.hero-inner {
  position: relative;
  z-index: 1;
  width: 100%;
  padding-block: 100px 112px;
}

.hero-content {
  max-width: 730px;
}

.hero .eyebrow {
  color: #e1b58f;
}

.hero h1 {
  max-width: 730px;
  margin-bottom: 28px;
  color: var(--white);
}

.hero h1 span {
  color: #dfad83;
}

.hero-description {
  max-width: 590px;
  margin-bottom: 34px;
  color: rgba(255, 255, 255, 0.82);
  font-size: clamp(17px, 1.7vw, 20px);
  line-height: 1.75;
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 14px;
}

.hero-note {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-top: 40px;
  color: rgba(255, 255, 255, 0.76);
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.035em;
}

.hero-note::before {
  width: 32px;
  height: 1px;
  background: var(--gold);
  content: "";
}

/* TRUST / BUSINESS APPROACH */

.trust-strip {
  background: var(--white);
  border-bottom: 1px solid var(--line);
}

.trust-inner {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  padding-block: 30px;
}

.trust-item {
  padding: 5px 28px;
  border-right: 1px solid var(--line);
}

.trust-item:first-child {
  padding-left: 0;
}

.trust-item:last-child {
  border-right: 0;
}

.trust-number {
  display: block;
  margin-bottom: 4px;
  color: var(--copper-dark);
  font-family: var(--font-heading);
  font-size: 27px;
  line-height: 1.2;
}

.trust-label {
  color: var(--muted);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.09em;
  text-transform: uppercase;
}

/* WHY CHOOSE US */

.why-section {
  background: var(--paper);
}

.why-layout {
  display: grid;
  grid-template-columns: 0.9fr 1.1fr;
  align-items: center;
  gap: clamp(45px, 8vw, 105px);
}

.why-image-wrap {
  position: relative;
  min-height: 540px;
}

.why-image {
  width: 100%;
  height: 540px;
  border-radius: var(--radius-sm);
  object-fit: cover;
  object-position: center;
  box-shadow: var(--shadow);
}

.why-image-accent {
  position: absolute;
  right: -18px;
  bottom: -18px;
  z-index: 0;
  width: 48%;
  height: 48%;
  border-right: 5px solid var(--copper);
  border-bottom: 5px solid var(--copper);
  pointer-events: none;
}

.why-content {
  position: relative;
  z-index: 1;
}

.why-content h2 {
  margin-bottom: 22px;
}

.why-content > p {
  color: var(--muted);
}

.why-points {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 24px 28px;
  margin-top: 36px;
}

.why-point {
  padding-top: 18px;
  border-top: 1px solid var(--line);
}

.why-point h3 {
  margin-bottom: 8px;
  font-family: var(--font-body);
  font-size: 14px;
  font-weight: 700;
  letter-spacing: 0;
}

.why-point p {
  margin: 0;
  color: var(--muted);
  font-size: 13px;
  line-height: 1.7;
}

.why-cta {
  margin-top: 36px;
}

/* ROOF ATTENTION SECTION */

.roof-section {
  background: var(--forest);
  color: rgba(255, 255, 255, 0.82);
}

.roof-layout {
  display: grid;
  grid-template-columns: 1fr 0.85fr;
  align-items: center;
  gap: clamp(45px, 8vw, 100px);
}

.roof-content h2 {
  margin-bottom: 24px;
  color: var(--white);
}

.roof-content > p {
  max-width: 570px;
  color: rgba(255, 255, 255, 0.75);
}

.roof-signs {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0 25px;
  margin-top: 34px;
}

.roof-sign {
  padding: 17px 0;
  border-top: 1px solid rgba(255, 255, 255, 0.2);
  color: var(--white);
  font-size: 14px;
  font-weight: 600;
}

.roof-sign::before {
  margin-right: 12px;
  color: #e1ad84;
  content: "—";
}

.roof-image-wrap {
  position: relative;
}

.roof-image {
  width: 100%;
  min-height: 430px;
  max-height: 550px;
  border-radius: var(--radius-sm);
  object-fit: cover;
  object-position: center;
}

.roof-image-caption {
  position: absolute;
  right: 0;
  bottom: 0;
  left: 0;
  padding: 20px 24px;
  background: linear-gradient(transparent, rgba(16, 29, 27, 0.88));
  color: var(--white);
  font-size: 12px;
  font-weight: 600;
}

/* COLORADO ROOFING GUIDE */

.guide-section {
  background: var(--white);
}

.guide-layout {
  display: grid;
  grid-template-columns: 0.72fr 1.28fr;
  gap: clamp(40px, 8vw, 100px);
}

.guide-heading {
  position: sticky;
  top: 35px;
  align-self: start;
}

.guide-heading h2 {
  margin-bottom: 22px;
}

.guide-heading p {
  color: var(--muted);
}

.guide-steps {
  border-top: 1px solid var(--line);
}

.guide-step {
  display: grid;
  grid-template-columns: 58px 1fr;
  gap: 22px;
  padding: 30px 0;
  border-bottom: 1px solid var(--line);
}

.guide-step-number {
  color: var(--copper);
  font-family: var(--font-heading);
  font-size: 28px;
  line-height: 1.2;
}

.guide-step h3 {
  margin-bottom: 10px;
  font-family: var(--font-body);
  font-size: 16px;
  font-weight: 700;
  letter-spacing: 0;
}

.guide-step p {
  max-width: 580px;
  margin: 0;
  color: var(--muted);
  font-size: 14px;
  line-height: 1.8;
}

/* RECENT PROJECTS */

.projects-section {
  background: var(--surface);
}

.projects-heading {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 35px;
  margin-bottom: 42px;
}

.projects-heading .section-heading {
  margin-bottom: 0;
}

.projects-heading p {
  max-width: 410px;
  margin-bottom: 5px;
  color: var(--muted);
  font-size: 14px;
}

.projects-grid {
  display: grid;
  grid-template-columns: 1.05fr 0.95fr;
  grid-template-rows: repeat(2, minmax(230px, 1fr));
  gap: 22px;
}

.project-card {
  position: relative;
  min-height: 250px;
  overflow: hidden;
  background: var(--forest);
  border-radius: var(--radius-sm);
}

.project-card:first-child {
  grid-row: span 2;
  min-height: 510px;
}

.project-card img {
  width: 100%;
  height: 100%;
  min-height: inherit;
  object-fit: cover;
  transition: transform 500ms ease;
}

.project-card:hover img {
  transform: scale(1.035);
}

.project-overlay {
  position: absolute;
  inset: 35% 0 0;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  padding: 28px;
  background: linear-gradient(
    transparent,
    rgba(17, 32, 29, 0.88)
  );
  color: var(--white);
}

.project-category {
  margin-bottom: 8px;
  color: #e9b58d;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.project-title {
  color: var(--white);
  font-family: var(--font-heading);
  font-size: 26px;
  line-height: 1.2;
}

.project-location {
  margin-top: 6px;
  color: rgba(255, 255, 255, 0.75);
  font-size: 12px;
}

/* ACCESSIBILITY AND MOTION */

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}
