/* CSS PART 2 OF 2 */

/* CONTACT AND CONVERSION */

.contact-section {
  position: relative;
  overflow: hidden;
  background: var(--paper);
}

.contact-layout {
  display: grid;
  grid-template-columns: 0.85fr 1.15fr;
  gap: clamp(40px, 7vw, 90px);
  align-items: start;
}

.contact-content h2 {
  margin-bottom: 24px;
}

.contact-content > p {
  max-width: 460px;
  color: var(--muted);
}

.contact-methods {
  display: grid;
  gap: 16px;
  margin-top: 38px;
}

.contact-method {
  display: flex;
  align-items: center;
  gap: 15px;
  padding: 17px 0;
  border-top: 1px solid var(--line);
}

.contact-method-icon {
  display: grid;
  width: 42px;
  height: 42px;
  flex: 0 0 42px;
  place-items: center;
  border-radius: 50%;
  background: #e9e6dd;
  color: var(--forest);
  font-size: 18px;
}

.contact-method-copy {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.contact-method-label {
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.contact-method a {
  color: var(--forest);
  font-size: 16px;
  font-weight: 700;
}

.contact-method a:hover {
  color: var(--copper-dark);
}

.contact-form-wrap {
  padding: clamp(28px, 4vw, 48px);
  background: var(--white);
  border: 1px solid var(--line);
  border-top: 4px solid var(--copper);
  border-radius: var(--radius-sm);
  box-shadow: var(--shadow);
}

.contact-form-heading {
  margin-bottom: 30px;
}

.contact-form-heading h3 {
  margin-bottom: 10px;
  font-size: 30px;
}

.contact-form-heading p {
  margin: 0;
  color: var(--muted);
  font-size: 14px;
}

.contact-form {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 20px;
}

.form-field {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 8px;
}

.form-field--full {
  grid-column: 1 / -1;
}

.form-field label {
  color: var(--ink-soft);
  font-size: 12px;
  font-weight: 700;
}

.form-field input,
.form-field select,
.form-field textarea {
  width: 100%;
  min-width: 0;
  min-height: 49px;
  padding: 12px 14px;
  border: 1px solid #d7d8d2;
  border-radius: var(--radius-sm);
  background: #fbfbf9;
  color: var(--ink);
  font-size: 14px;
  transition:
    border-color var(--transition),
    background var(--transition),
    box-shadow var(--transition);
}

.form-field textarea {
  min-height: 130px;
  resize: vertical;
}

.form-field input:hover,
.form-field select:hover,
.form-field textarea:hover {
  border-color: #9ba9a2;
}

.form-field input:focus,
.form-field select:focus,
.form-field textarea:focus {
  border-color: var(--forest);
  outline: 3px solid rgba(38, 63, 59, 0.15);
  outline-offset: 1px;
  background: var(--white);
}

.form-field input::placeholder,
.form-field textarea::placeholder {
  color: #858d8a;
}

.form-submit {
  grid-column: 1 / -1;
  width: 100%;
  margin-top: 5px;
}

.form-disclaimer {
  grid-column: 1 / -1;
  margin: 0;
  color: var(--muted);
  font-size: 11px;
  line-height: 1.6;
}

/* FINAL CALL TO ACTION */

.final-cta {
  padding-block: 65px;
  background: var(--forest-deep);
  color: var(--white);
}

.final-cta-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 40px;
}

.final-cta h2 {
  max-width: 680px;
  color: var(--white);
  font-size: clamp(30px, 4vw, 43px);
}

.final-cta p {
  margin: 12px 0 0;
  color: rgba(255, 255, 255, 0.7);
  font-size: 14px;
}

.final-cta-actions {
  display: flex;
  flex: 0 0 auto;
  flex-wrap: wrap;
  gap: 12px;
}

/* FOOTER */

.site-footer {
  padding-block: 48px 24px;
  background: #152825;
  color: rgba(255, 255, 255, 0.72);
}

.footer-main {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 50px;
  padding-bottom: 38px;
}

.footer-brand {
  max-width: 380px;
}

.footer-brand .brand-name {
  color: var(--white);
}

.footer-brand .brand-description {
  color: rgba(255, 255, 255, 0.58);
}

.footer-brand p {
  margin-top: 20px;
  color: rgba(255, 255, 255, 0.65);
  font-size: 13px;
}

.footer-links {
  display: flex;
  flex-wrap: wrap;
  gap: 18px 30px;
}

.footer-links a {
  color: rgba(255, 255, 255, 0.8);
  font-size: 12px;
  font-weight: 600;
}

.footer-links a:hover {
  color: #e5b48e;
}

.footer-bottom {
  display: flex;
  justify-content: space-between;
  gap: 20px;
  padding-top: 22px;
  border-top: 1px solid rgba(255, 255, 255, 0.16);
  color: rgba(255, 255, 255, 0.55);
  font-size: 11px;
}

/* ACCESSIBLE MOBILE MENU */

.menu-toggle {
  display: none;
  width: 46px;
  height: 46px;
  flex: 0 0 46px;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 5px;
  padding: 0;
  border: 1px solid var(--line);
  border-radius: var(--radius-sm);
  background: var(--white);
  color: var(--forest);
}

.menu-toggle span[aria-hidden="true"] {
  display: block;
  width: 20px;
  height: 2px;
  flex: 0 0 2px;
  background-color: currentColor;
}

/* RESPONSIVE: TABLETS */

@media (max-width: 1000px) {
  :root {
    --section-space: 82px;
  }

  .header-inner {
    gap: 18px;
  }

  .main-nav {
    gap: 17px;
  }

  .header-phone {
    display: none;
  }

  .why-layout {
    gap: 48px;
  }

  .why-image-wrap,
  .why-image {
    min-height: 450px;
    height: 450px;
  }

  .roof-layout {
    gap: 42px;
  }

  .guide-layout {
    gap: 45px;
  }

  .contact-layout {
    gap: 42px;
  }
}

/* RESPONSIVE: MOBILE NAVIGATION */

@media (max-width: 760px) {
  :root {
    --gutter: 24px;
    --section-space: 70px;
  }

  html {
    scroll-padding-top: 76px;
  }

  .header-inner {
    position: relative;
    min-height: 76px;
    flex-wrap: wrap;
  }

  .brand {
    gap: 10px;
  }

  .brand img {
    width: 58px;
    height: 54px;
  }

  .brand-name {
    font-size: 16px;
  }

  .brand-description {
    font-size: 8px;
  }

  .menu-toggle {
    display: flex;
  }

  .main-nav {
    display: none;
    width: 100%;
    flex: 0 0 100%;
    flex-direction: column;
    align-items: stretch;
    justify-content: flex-start;
    gap: 0;
    padding: 8px 0 20px;
    border-top: 1px solid var(--line);
  }

  .main-nav.is-open {
    display: flex;
  }

  .main-nav a:not(.button) {
    display: block;
    width: 100%;
    padding: 13px 4px;
    border-bottom: 1px solid var(--line);
    font-size: 14px;
  }

  .main-nav a:not(.button)::after {
    display: none;
  }

  .main-nav .button {
    width: 100%;
    margin-top: 14px;
  }

  .hero {
    min-height: 610px;
  }

  .hero::before {
    background:
      linear-gradient(
        90deg,
        rgba(20, 39, 36, 0.94),
        rgba(20, 39, 36, 0.68)
      ),
      url("https://joshbrooksconstructionllc.com/wp-content/uploads/2026/09/finished-roof-ridge-thornton-co-768x1024.jpg")
        center / cover no-repeat;
  }

  .hero-inner {
    padding-block: 85px 95px;
  }

  .hero h1 {
    font-size: clamp(43px, 10vw, 62px);
  }

  .hero-description {
    font-size: 17px;
  }

  .hero-actions {
    align-items: stretch;
  }

  .hero-actions .button {
    width: 100%;
  }

  .trust-inner {
    grid-template-columns: 1fr;
    padding-block: 10px;
  }

  .trust-item,
  .trust-item:first-child {
    padding: 17px 0;
    border-right: 0;
    border-bottom: 1px solid var(--line);
  }

  .trust-item:last-child {
    border-bottom: 0;
  }

  .why-layout,
  .roof-layout,
  .guide-layout,
  .contact-layout {
    grid-template-columns: 1fr;
    gap: 38px;
  }

  .why-image-wrap,
  .why-image {
    min-height: 340px;
    height: 340px;
  }

  .why-image-accent {
    right: -8px;
    bottom: -8px;
  }

  .why-points {
    gap: 20px;
  }

  .roof-signs {
    gap: 0 18px;
  }

  .roof-image {
    min-height: 330px;
    max-height: 420px;
  }

  .guide-heading {
    position: static;
  }

  .guide-step {
    grid-template-columns: 42px minmax(0, 1fr);
    gap: 15px;
    padding-block: 24px;
  }

  .projects-heading {
    display: block;
  }

  .projects-heading p {
    margin-top: 18px;
  }

  .projects-grid {
    grid-template-columns: 1fr;
    grid-template-rows: auto;
    gap: 16px;
  }

  .project-card,
  .project-card:first-child {
    grid-row: auto;
    min-height: 330px;
  }

  .contact-form-wrap {
    padding: 27px 22px;
  }

  .final-cta-inner {
    align-items: flex-start;
    flex-direction: column;
  }

  .final-cta-actions {
    width: 100%;
  }

  .final-cta-actions .button {
    flex: 1 1 100%;
  }

  .footer-main {
    flex-direction: column;
    gap: 30px;
  }

  .footer-bottom {
    flex-direction: column;
    gap: 8px;
  }
}

/* RESPONSIVE: SMALL PHONES */

@media (max-width: 480px) {
  :root {
    --gutter: 19px;
    --section-space: 60px;
  }

  body {
    font-size: 15px;
  }

  h2 {
    font-size: 36px;
  }

  .brand img {
    width: 48px;
    height: 48px;
  }

  .brand-name {
    max-width: 190px;
    font-size: 14px;
  }

  .brand-description {
    max-width: 190px;
    font-size: 7px;
  }

  .hero {
    min-height: 570px;
  }

  .hero-inner {
    padding-block: 70px 80px;
  }

  .hero h1 {
    font-size: 43px;
  }

  .hero-note {
    align-items: flex-start;
    font-size: 11px;
  }

  .why-points,
  .roof-signs {
    grid-template-columns: 1fr;
  }

  .why-image-wrap,
  .why-image {
    min-height: 290px;
    height: 290px;
  }

  .roof-image {
    min-height: 280px;
  }

  .project-card,
  .project-card:first-child {
    min-height: 285px;
  }

  .project-overlay {
    padding: 20px;
  }

  .contact-form {
    grid-template-columns: 1fr;
    gap: 16px;
  }

  .form-field--full,
  .form-submit,
  .form-disclaimer {
    grid-column: 1;
  }

  .contact-form-wrap {
    padding: 23px 17px;
  }

  .final-cta {
    padding-block: 52px;
  }

  .footer-links {
    gap: 15px 20px;
  }
}

/* KEYBOARD FOCUS */

.menu-toggle:focus-visible,
.button:focus-visible,
.main-nav a:focus-visible,
.footer-links a:focus-visible,
.contact-method a:focus-visible,
.form-field input:focus-visible,
.form-field select:focus-visible,
.form-field textarea:focus-visible {
  outline: 3px solid var(--copper);
  outline-offset: 4px;
}

/* REDUCED MOTION */

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }

  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }

  .project-card:hover img,
  .button:hover {
    transform: none;
  }
}
